package db

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"os"
	"testing"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

// Import the actual synthetic pre102 snapshot generated by frozen188. Historical
// source and proof bytes must not be reconstructed using the current104 signer.
func loadActualPre102Fixture196(t *testing.T, p *pgxpool.Pool) {
	t.Helper()
	raw, err := os.ReadFile("testdata/pre102-proof196.json")
	if err != nil {
		t.Fatal(err)
	}
	meta, err := os.ReadFile("testdata/pre102-proof196-provenance.json")
	if err != nil {
		t.Fatal(err)
	}
	var proof struct {
		Hash   string `json:"fixture_sha256"`
		Frozen string `json:"frozen_manifest_sha256"`
	}
	if err = json.Unmarshal(meta, &proof); err != nil {
		t.Fatal(err)
	}
	digest := sha256.Sum256(raw)
	if proof.Hash != hex.EncodeToString(digest[:]) || proof.Frozen != "3d4e3ff878a7e2f4225a91a6d8ac01cebdb7c97bac2f38ecebb45ee510421536" {
		t.Fatal("historical fixture provenance mismatch")
	}
	var fixture struct {
		Synthetic  bool                       `json:"synthetic_only"`
		Production bool                       `json:"production"`
		RealFunds  bool                       `json:"real_funds"`
		Tables     map[string]json.RawMessage `json:"tables"`
		Sequences  map[string]struct {
			Last   int64 `json:"last_value"`
			Called bool  `json:"is_called"`
		} `json:"sequences"`
	}
	if err = json.Unmarshal(raw, &fixture); err != nil || !fixture.Synthetic || fixture.Production || fixture.RealFunds {
		t.Fatal("synthetic historical fixture required", err)
	}
	ctx := t.Context()
	tx, err := p.Begin(ctx)
	if err != nil {
		t.Fatal(err)
	}
	defer tx.Rollback(ctx)
	// The original birth trigger intentionally prohibits importing old timestamps.
	// Disable only that trigger while restoring the fixed historical fixture;
	// retain all FK/check constraints and restore the trigger before commit.
	if _, err = tx.Exec(ctx, `ALTER TABLE referral_order_terms DISABLE TRIGGER referral_terms_birth`); err != nil {
		t.Fatal(err)
	}
	order := []string{"merchants", "accounts", "provider_route_assignments", "provider_route_fee_quotes", "orders", "order_route_fee_terms", "referral_order_terms", "order_print_origins", "provider_channel_last_used"}
	if len(fixture.Tables) != len(order) {
		t.Fatal("unexpected fixture tables")
	}
	for _, table := range order {
		rows, ok := fixture.Tables[table]
		if !ok {
			t.Fatal("missing fixture table", table)
		}
		name := pgx.Identifier{table}.Sanitize()
		if _, err = tx.Exec(ctx, `INSERT INTO `+name+` SELECT * FROM json_populate_recordset(NULL::`+name+`,$1::json)`, string(rows)); err != nil {
			t.Fatal(table, err)
		}
	}
	if _, err = tx.Exec(ctx, `SET CONSTRAINTS ALL IMMEDIATE; ALTER TABLE referral_order_terms ENABLE TRIGGER referral_terms_birth`); err != nil {
		t.Fatal(err)
	}
	for sequence, state := range fixture.Sequences {
		if _, err = tx.Exec(ctx, `SELECT setval((current_schema()||'.'||$1)::regclass,$2,$3)`, sequence, state.Last, state.Called); err != nil {
			t.Fatal(sequence, err)
		}
	}
	if err = tx.Commit(ctx); err != nil {
		t.Fatal(err)
	}
}
